'use strict';
let onlinePollFailures=0,onlinePollBusy=false;
let onlineAuthenticated=null,onlineSearching=false,onlineBusy=false,onlineTimer=null,onlineJoinedAt=0,onlineEditor=false,onlineClock=null,onlineRecord=null,onlineRuleSelected='balanced';
const onlineEl=id=>document.getElementById(id);
function setOnlineAuthenticated(value){onlineAuthenticated=value;document.querySelectorAll('.online-sign-in').forEach(el=>el.hidden=value!==false);renderOnlineLobby();}
function onlineSetupCost(){const setup=resolvedFriendSetup();return {setup,cost:KanjiOnlineRules.total(setup.items.map(slot=>({...KANJI_DATABASE.find(b=>b.char===slot.char),equippedReadings:slot.equippedReadings})))};}
function onlineStatus(text){onlineEl('online-status').textContent=text;}
function renderOnlineLobby(){
 const {setup,cost}=onlineSetupCost(),room=friendRoom?.mode==='online'?friendRoom:null,playing=room?.status==='playing',preparing=room?.status==='preparing';if(room)onlineRuleSelected=KanjiOnlineRules.roomRule(room);const balanced=onlineRuleSelected==='balanced';onlineEl('online-rule').value=onlineRuleSelected;onlineEl('online-rule').disabled=!!room||onlineSearching||onlineBusy;onlineEl('online-rule-note').textContent=KanjiOnlineRules.description(onlineRuleSelected);onlineEl('online-deck').textContent='対戦用：'+setup.items.map(i=>i.char).join('・')+(balanced?' ／ 全員Lv.10':' ／ '+setup.items.map(i=>'Lv.'+i.level).join('・'));onlineEl('online-cost').textContent=balanced?`編成コスト ${cost} / ${KanjiOnlineRules.budget}（${KanjiOnlineRules.costGuide}）`:'自由ルールは編成コストの上限なし。現在のレベル・装備ルビがそのまま反映されます。';onlineEl('online-cost').style.color=balanced&&cost>16?'#fda4af':'';
 if(onlineRecord)onlineEl('online-record').textContent=`${KanjiOnlineRules.label(onlineRuleSelected)}：${onlineRecord.rank}・${onlineRecord.rating} 対人RP ／ ${onlineRecord.wins}勝 ${onlineRecord.losses}敗 ${onlineRecord.draws}分`;
 onlineEl('btn-online-search').hidden=!!room||onlineSearching;onlineEl('btn-online-search').disabled=onlineAuthenticated!==true||onlineBusy||balanced&&cost>16||setup.items.length!==3;
 onlineEl('btn-online-cancel').hidden=!onlineSearching;onlineEl('btn-online-cancel').disabled=onlineBusy;onlineEl('btn-online-deck').disabled=onlineAuthenticated!==true||onlineBusy||onlineSearching||playing;onlineEl('btn-online-resume').hidden=!playing&&!preparing;onlineEl('btn-online-resume').textContent=preparing?'相手確認・スタート画面に戻る':'盤面に戻る';onlineEl('btn-online-leave').hidden=!room||['preparing','playing'].includes(room.status)&&!room.departed;onlineEl('btn-online-leave').textContent=playing?'退出（敗北）':'部屋から退出';onlineEl('btn-online-leave').disabled=onlineBusy;onlineEl('btn-online-next').hidden=room?.status!=='finished';onlineEl('btn-online-next').disabled=onlineBusy;
}
window.openOnlineLobby=async()=>{pausePlayerOverlay();document.getElementById('modal-friends').classList.add('hidden');onlineEl('modal-online').classList.remove('hidden');renderOnlineLobby();try{const session=await playerApi('/api/session');setOnlineAuthenticated(session.authenticated);if(!session.authenticated){onlineEl('online-record').textContent='ゲストの接続を確認してください。';onlineStatus('ひとり用モードはログインなしで遊べます。');return;}await loadFriendSetup();await loadOnlineRecord();renderOnlineLobby();if(!friendRoom&&!onlineSearching){const result=await playerApi('/api/online/queue');acceptOnlineQueue(result);}}catch(error){onlineStatus(error.message);}};
window.closeOnlineLobby=()=>{onlineEl('modal-online').classList.add('hidden');resumePlayerEngine();onlineEl('btn-online-lobby').focus();};
function acceptOnlineHonors(stats){if(!stats?.achievementProgress)return;acceptHonorProgress(stats.achievementProgress);saveState();if(profileDraft)renderProfileHonors();}
async function loadOnlineRecord(){const selected=onlineRuleSelected,result=await playerApi('/api/online/stats?rule='+selected);if(selected===onlineRuleSelected){onlineRecord=result;acceptOnlineHonors(result);renderOnlineLobby();}}
window.setOnlineRule=async value=>{if(onlineBusy||onlineSearching||friendRoom||!KanjiOnlineRules.validRule(value))return;onlineRuleSelected=value;onlineRecord=null;onlineEl('online-record').textContent='記録を読み込み中…';renderOnlineLobby();if(onlineAuthenticated)try{await loadOnlineRecord();}catch(error){onlineStatus(error.message);}};
function rememberOnlineQueue(value){try{if(value)sessionStorage.setItem('kanji_online_search','1');else sessionStorage.removeItem('kanji_online_search');}catch{}}
function acceptOnlineQueue(result){if(result.status==='matched'&&result.room){onlineSearching=false;rememberOnlineQueue(false);clearTimeout(onlineTimer);onlineEl('modal-online').classList.add('hidden');acceptFriendRoom(result.room,false);startFriendPolling();onlineRecord=result.room.onlineStats;renderOnlineLobby();return;}const changed=result.ruleSet&&result.ruleSet!==onlineRuleSelected;if(result.ruleSet)onlineRuleSelected=result.ruleSet;if(changed){onlineRecord=null;onlineEl('online-record').textContent='記録を読み込み中…';loadOnlineRecord().catch(()=>{onlineEl('online-record').textContent='対人記録を読み込めません。再接続後に確認できます。';});}onlineSearching=result.status==='waiting';rememberOnlineQueue(onlineSearching);onlineJoinedAt=result.joinedAt||0;if(onlineSearching){const seconds=Math.max(0,Math.floor((Date.now()-onlineJoinedAt)/1000));onlineStatus(`対戦相手を探しています… ${seconds}秒 ／ 検索範囲 ±${result.range} 対人RP。相手がいない場合はこのまま待つか、取り消せます。`);scheduleOnlinePoll();}else onlineStatus('相手探しを開始できます。');renderOnlineLobby();}
function onlinePollDelay(){return KanjiNetwork.delay(Date.now()-onlineJoinedAt>=30000?5000:3000,onlinePollFailures,30000);}
function scheduleOnlinePoll(){clearTimeout(onlineTimer);if(onlineSearching&&!document.hidden)onlineTimer=setTimeout(pollOnlineQueue,onlinePollDelay());}
async function pollOnlineQueue(){if(!onlineSearching||document.hidden||onlinePollBusy)return;onlinePollBusy=true;clearTimeout(onlineTimer);try{const result=await playerApi('/api/online/queue');onlinePollFailures=0;if(onlineSearching)acceptOnlineQueue(result);}catch(error){onlinePollFailures++;onlineStatus(error.message+' 接続が戻ると再確認します。');}finally{onlinePollBusy=false;scheduleOnlinePoll();}}
window.startOnlineSearch=async()=>{if(onlineBusy||onlineSearching)return;if(friendRoom){onlineStatus('参加中の対局から退出してから検索できます。');return;}onlineBusy=true;renderOnlineLobby();onlineStatus('編成を確認して、相手を探します…');try{await loadFriendSetup();await ensurePlayerProfile();const team=friendRoster();acceptOnlineQueue(await playerApi('/api/online/queue','POST',{...team,ruleSet:onlineRuleSelected}));}catch(error){onlineStatus(error.message);}finally{onlineBusy=false;renderOnlineLobby();}};
window.cancelOnlineSearch=async()=>{if(onlineBusy)return;onlineBusy=true;renderOnlineLobby();try{const result=await playerApi('/api/online/cancel','POST',{});if(result.room){acceptFriendRoom(result.room,false);onlineSearching=false;clearTimeout(onlineTimer);rememberOnlineQueue(false);onlineStatus('マッチが成立しました。対局終了まで退出できません。');return;}onlineSearching=false;clearTimeout(onlineTimer);rememberOnlineQueue(false);onlineStatus('相手探しを取り消しました。');}catch(error){onlineStatus(error.message+' 取り消しをもう一度お試しください。');}finally{onlineBusy=false;renderOnlineLobby();}};
window.leaveOnlineMatch=async()=>{if(onlineBusy)return;if(friendRoom?.mode==='online'&&['preparing','playing'].includes(friendRoom.status)&&!friendRoom.departed){showToast('マッチ成立後は対局終了まで退出できません。');return;}onlineBusy=true;renderOnlineLobby();try{await leaveFriendRoom();if(friendRoom)throw Error('退出を完了できませんでした。');await playerApi('/api/online/cancel','POST',{});document.getElementById('modal-battle-menu').classList.add('hidden');switchTab('matches');await openOnlineLobby();}catch(error){onlineStatus(error.message);}finally{onlineBusy=false;renderOnlineLobby();}};
window.nextOnlineMatch=async()=>{if(onlineBusy||friendRoom&&friendRoom.status!=='finished')return;onlineBusy=true;renderOnlineLobby();try{if(friendRoom)await leaveFriendRoom();if(friendRoom)throw Error('退出を完了できませんでした。');onlineEl('modal-result').classList.add('hidden');await playerApi('/api/online/cancel','POST',{});}catch(error){onlineStatus(error.message);onlineBusy=false;renderOnlineLobby();return;}onlineBusy=false;await openOnlineLobby();await startOnlineSearch();};
window.openOnlineDeckEditor=async()=>{if(onlineSearching||onlineBusy)return;onlineEditor=true;await openFriendDeckEditor();if(friendDeckDraft)onlineEl('modal-online').classList.add('hidden');else onlineEditor=false;};
const friendLobbyBeforeOnline=window.openFriendLobby;
window.openFriendLobby=()=>{if(onlineEditor||onlineSearching||friendRoom?.mode==='online'){onlineEditor=false;return openOnlineLobby();}return friendLobbyBeforeOnline();};
const friendSummaryBeforeOnline=renderFriendDeckSummary;
renderFriendDeckSummary=function(){friendSummaryBeforeOnline();renderOnlineLobby();};
function renderOnlineBattle(room){onlineRecord=room.onlineStats;acceptOnlineHonors(room.onlineStats);onlineRuleSelected=KanjiOnlineRules.roomRule(room);onlineEl('cpu-rank').textContent='オンライン・'+KanjiOnlineRules.label(onlineRuleSelected);onlineEl('battle-guide-text').textContent=room.state.finished?'対局終了・次の相手を探せます':room.state.turn===room.side?'文字を選び、点線内の空き場所を引いて発射':'相手の発射を待っています';renderOnlineClock(room);renderOnlineLobby();}
function renderOnlineClock(room){clearInterval(onlineClock);const deadline=room.deadline+(Date.now()-room.serverNow);const update=()=>{if(friendRoom?.code!==room.code||room.state.finished)return;const seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));onlineEl('friend-turn-status').textContent=`${room.state.turn===room.side?'あなた':'相手'}の番・残り${seconds}秒${seconds===0?'（再接続の確認中）':''}`;};update();if(!room.state.finished)onlineClock=setInterval(update,250);}
function renderOnlineResult(room){clearInterval(onlineClock);onlineEl('btn-friend-next').hidden=true;onlineEl('btn-friend-result-deck').hidden=true;onlineEl('btn-online-result-next').hidden=false;onlineEl('btn-result-close').textContent='オンライン対戦に戻る';onlineEl('result-rp-change').textContent=(room.ratingChange>=0?'+':'')+(room.ratingChange||0)+' 対人RP';onlineEl('result-rp-change').className='font-bold text-cyan-300';onlineEl('result-message').textContent=`${room.state.reason}で決着しました。${room.onlineStats.rank}・${room.onlineStats.rating} 対人RP。`;onlineEl('result-coin-change').textContent='変動なし';onlineRecord=room.onlineStats;acceptOnlineHonors(room.onlineStats);renderOnlineLobby();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(onlineTimer);else if(onlineSearching)pollOnlineQueue();});window.addEventListener('online',()=>{if(onlineSearching)pollOnlineQueue();});
window.addEventListener('load',()=>{if(new URLSearchParams(location.search).get('online')==='1')openOnlineLobby();else{let resume=false;try{resume=sessionStorage.getItem('kanji_online_search')==='1';}catch{}if(resume)openOnlineLobby();}});

const friendFinishBeforeOnline=finishFriendDisplay;
finishFriendDisplay=function(room){friendFinishBeforeOnline(room);if(room.mode==='online'&&!friendAnimating){if(room.state.finished){renderOnlineResult(room);onlineEl('battle-guide-text').textContent='対局終了・次の相手を探せます';}}};
